def build_questions() -> list[dict[str, Any]]:
    questions: list[dict[str, Any]] = []
    for spec in _QUESTION_SPECS:
        (
            question_id, topic, subtopic, difficulty, minutes, prompt, correct,
            distractors, explanation, distractor_explanations,
        ) = spec
        options = {"A": correct, **dict(zip(("B", "C", "D"), distractors))}
        option_explanations = {
            "A": explanation,
            **dict(zip(("B", "C", "D"), distractor_explanations)),
        }
        questions.append({
            "question_id": question_id,
            "question": prompt,
            "role": "Software engineer",
            "role_family": "general",
            "experience_level": "adaptive",
            "interview_category": "Technical",
            "focus_area": topic,
            "topic": topic,
            "course_section": "Data Structures and Algorithms" if question_id.startswith(
                ("arrays-", "strings-", "hashing-", "sorting-", "binary-", "linked-", "backtracking-", "bit-", "stacks-", "queues-", "sliding-", "two-pointers-", "heap-", "greedy-", "trees-", "graphs-", "dynamic-", "tries-")
            ) else topic,
            "subtopic": subtopic,
            "difficulty": difficulty,
            "estimated_time_minutes": minutes,
            "question_type": "Multiple choice",
            "format": "multiple_choice",
            "concept_id": f"interviewready-{question_id}-concept",
            "scenario_id": f"interviewready-{question_id}-scenario",
            "follow_up_to_question_id": "",
            "expected_answer": correct,
            "explanation": explanation,
            "evaluation_criteria": [explanation],
            "tags": [topic.casefold(), subtopic.casefold(), "original-question"],
            "source": "InterviewReady AI original question",
            "source_reference": DSA_REFERENCE,
            "options": options,
            "correct_option": "A",
            "option_explanations": option_explanations,
        })
    return questions


